import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC01%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E5%8C%96%E5%8F%91%E5%B1%95/1.5%20%E6%95%B0%E5%AD%97%E5%8C%96%E8%BD%AC%E5%9E%8B%E4%B8%8E%E5%85%83%E5%AE%87%E5%AE%99.html","title":"1.5 数字化转型与元宇宙","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第01章 信息化发展/1.5 数字化转型与元宇宙.md"}`),a={name:`1.5 数字化转型与元宇宙.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_1-5-数字化转型与元宇宙" tabindex="-1"><a class="header-anchor" href="#_1-5-数字化转型与元宇宙"><span>1.5 数字化转型与元宇宙</span></a></h1><h2 id="一、元宇宙" tabindex="-1"><a class="header-anchor" href="#一、元宇宙"><span>一、元宇宙</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><ol><li>元宇宙（Metaverse）是一大批技术的集成</li><li>陈刚教授的定义：元宇宙是利用科技手段进行链接与创造的，与现实世界映射与交互的虚拟世界，具备新型社会体系的数字生活空间</li><li>沈阳教授的定义：基于扩展现实技术AR提供沉浸式体验，以及数字孪生技术生成现实世界的镜像，通过区块链技术搭建经济体系，将虚拟世界与现实世界在经济系统、社交系统、身份系统上密切融合，并且允许每个用户进行内容生产和编辑</li><li>左鹏飞：从时空性、真实性、独立性、连接性四个方面交叉定义</li></ol><h3 id="主要特征" tabindex="-1"><a class="header-anchor" href="#主要特征"><span>主要特征</span></a></h3><ol><li>沉浸式体验——即时信息基础上的沉浸式体验</li><li>虚拟身份——人们已经拥有大量的互联网账号，一个或若干个数字身份</li><li>虚拟经济——这些活动需要一定的经济模式展开，即虚拟经济</li><li>虚拟社会治理——需要一定的法律法规和规则的约束</li></ol><h3 id="发展演进" tabindex="-1"><a class="header-anchor" href="#发展演进"><span>发展演进</span></a></h3><ol><li>元宇宙首先会在社交、娱乐和文化领域发展，形成虚拟&quot;数字人&quot;，逐步再向虚拟身份方向演进，形成&quot;数字人生&quot;，此时偏向个体用户需求</li><li>三元空间——物理空间、社会空间、信息空间</li></ol><h3 id="三元空间定义" tabindex="-1"><a class="header-anchor" href="#三元空间定义"><span>三元空间定义</span></a></h3><p>是建立在数字化转换、数字化升级基础上，进一步触及组织核心业务，以新建一种业务模式为目标的高层次转型</p><p>人类社会的三元空间：信息空间、物理空间、社会空间</p><p>【口诀：无色系】</p><h2 id="二、数字化转型" tabindex="-1"><a class="header-anchor" href="#二、数字化转型"><span>二、数字化转型</span></a></h2><h3 id="驱动因素" tabindex="-1"><a class="header-anchor" href="#驱动因素"><span>驱动因素</span></a></h3><ol><li>生产力飞升：第四次科技革命 第一科学范式为经验范式 第二科学范式为理论范式 第三科学范式为模拟范式 第四科学范式为数据密集型研究范式</li><li>生产要素变化：数据是与土地、劳动力、资本和技术并列的主要生产要素</li><li>信息传播效率突破：社会互联网新格局，社交网络信息传输具有永久性、无限性、即时性以及方向性的特征</li><li>社会&quot;智慧主体&quot;规模：快速复制与智能 社会的&quot;智慧主体&quot;已经不单纯是自然人，可是一个互联网账号、一台自动驾驶的汽车、一部智能手机，或工厂中的一套智能机器人</li></ol><h3 id="基本原理" tabindex="-1"><a class="header-anchor" href="#基本原理"><span>基本原理</span></a></h3><ol><li>能力因子定义和数字化&quot;封装&quot; 总结：将复杂业务解构为可量化、可调度的最小能力单元，形成【能力域—子域—项—分项】的层级结构，并通过【人员+技术+资源+数据+流程】的标准化封装，转化为数字化组件</li><li>基于&quot;互联网+&quot;的调度和决策 总结：将行业知识（如司机经验、交通规则）转化为算法模型，实现决策自动化，摆脱对个人经验的依赖</li><li>转型控制 不是指一个结果的表达，而是一个持续的过程</li></ol><h3 id="智慧转移" tabindex="-1"><a class="header-anchor" href="#智慧转移"><span>智慧转移</span></a></h3><p>个体智慧（知识、技能和经验等）由&quot;自然人个体&quot;转移到组织智慧（计算机、信息系统等掌握的）</p><h4 id="_1-智慧数据-信息化的过程-信息系统规划、建设、运行过程" tabindex="-1"><a class="header-anchor" href="#_1-智慧数据-信息化的过程-信息系统规划、建设、运行过程"><span>1. 智慧数据（信息化的过程，信息系统规划、建设、运行过程）</span></a></h4><p>内容：</p><ol><li>智慧结构化——明确了业务体系层面的内容</li><li>知识模型化——定义业务活动的逻辑关系</li><li>过程信息化——明确各执行操作系列要求</li><li>数据平台化——实现了数据的采集、存储和共享</li></ol><h4 id="_2-数据智慧-智慧化的过程-数据的开发利用和资源管理的过程" tabindex="-1"><a class="header-anchor" href="#_2-数据智慧-智慧化的过程-数据的开发利用和资源管理的过程"><span>2. 数据智慧（智慧化的过程，数据的开发利用和资源管理的过程）</span></a></h4><p>内容：</p><ol><li>对象数字化——实现对各类对象的数字化表达</li><li>孪生虚拟化——完成物理对象到信息空间的映射</li><li>架构可视化——实现业务知识模型与经验沉淀的复用和创新</li><li>计算智能化——实现多元条件下的调度和决策</li></ol><p>补充：S&amp;D模型就是基于DIKW模型，构筑了智慧-数据、数据-智慧两大过程的8个转化活动</p><h3 id="持续迭代活动" tabindex="-1"><a class="header-anchor" href="#持续迭代活动"><span>持续迭代活动</span></a></h3><ol><li>信息物理世界屏建设 先给现实中的每个东西（人、设备）建一个一模一样的虚拟模型，实时同步状态【建模】</li><li>决策能力边际化部署 让第一线的设备和员工拥有&quot;小脑筋&quot;，能自己快速做一些现场的小决定，不用事事请示【给大脑】</li><li>科学社会物理博弈机制构筑 建立一套&quot;团队协作规则&quot;，让所有虚拟模型和&quot;小脑筋&quot;能互相配合，像一个大团队一样，共同完成复杂任务【联成网】</li><li>数字框架与信息调制 确保所有模型和大脑之间的信息传递是高清、无延迟、无错误的，这是所有智能化的基础【强信号】</li></ol>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};